<script>
  // THE LIVING COMPONENT GALLERY (Stage 1): every base, portal and website component, on the account's theme. Not linked, not indexed. Used to render-check light and dark at 1440 and 390.
  import AppearanceMenu from "$lib/ui/AppearanceMenu.svelte";
  import Toggle from "$lib/ui/Toggle.svelte"; import Segment from "$lib/ui/Segment.svelte"; import Tabs from "$lib/ui/Tabs.svelte"; import Dialog from "$lib/ui/Dialog.svelte"; import Menu from "$lib/ui/Menu.svelte";
  import Tip from "$lib/ui/Tip.svelte"; import CopyButton from "$lib/ui/CopyButton.svelte"; import PinCode from "$lib/ui/PinCode.svelte"; import Meter from "$lib/ui/Meter.svelte"; import Range from "$lib/ui/Range.svelte"; import Kbd from "$lib/ui/Kbd.svelte";
  import StatusChip from "$lib/ui/StatusChip.svelte"; import RelativeTime from "$lib/ui/RelativeTime.svelte"; import EmptyState from "$lib/ui/EmptyState.svelte"; import PageHeader from "$lib/ui/PageHeader.svelte"; import FilterSelect from "$lib/ui/FilterSelect.svelte"; import DataTable from "$lib/ui/DataTable.svelte";
  import DetailHeader from "$lib/ui/DetailHeader.svelte"; import MetaGrid from "$lib/ui/MetaGrid.svelte"; import CopyField from "$lib/ui/CopyField.svelte"; import SecretField from "$lib/ui/SecretField.svelte"; import Timeline from "$lib/ui/Timeline.svelte"; import StatTile from "$lib/ui/StatTile.svelte"; import Spark from "$lib/ui/Spark.svelte"; import Bars from "$lib/ui/Bars.svelte"; import AreaChart from "$lib/ui/AreaChart.svelte"; import LegendRow from "$lib/ui/LegendRow.svelte"; import RateCard from "$lib/ui/RateCard.svelte"; import Ring from "$lib/ui/Ring.svelte"; import IntegrationCard from "$lib/ui/IntegrationCard.svelte";
  import Frame from "$lib/ui/Frame.svelte"; import CodeWindow from "$lib/ui/CodeWindow.svelte"; import Flow from "$lib/ui/Flow.svelte"; import EmailPreview from "$lib/ui/EmailPreview.svelte"; import Paper from "$lib/ui/Paper.svelte"; import Brand from "$lib/ui/Brand.svelte"; import Icon from "$lib/ui/Icon.svelte";
  import RainbowPill from "$lib/site/RainbowPill.svelte"; import GradientText from "$lib/site/GradientText.svelte"; import DotGrid from "$lib/site/DotGrid.svelte"; import EventPicker from "$lib/site/EventPicker.svelte"; import PlanCard from "$lib/site/PlanCard.svelte"; import VolumeSlider from "$lib/site/VolumeSlider.svelte"; import CompareTable from "$lib/site/CompareTable.svelte"; import ChangelogEntry from "$lib/site/ChangelogEntry.svelte"; import MethodPill from "$lib/site/MethodPill.svelte"; import ParamRow from "$lib/site/ParamRow.svelte"; import CodePanel from "$lib/site/CodePanel.svelte"; import CopyPage from "$lib/site/CopyPage.svelte";
  let on = $state(true), seg = $state("board"), tab = $state("a"), dlg = $state(false), pin = $state(""), vol = $state(500), rng = $state(40), status = $state(""), sel = $state("e1");
  const now = Date.now();
  const rows = [{ id: "1", name: "NDA, Dana Reyes", status: "Waiting", at: now - 3 * 60000 }, { id: "2", name: "Coaching agreement", status: "Signed", at: now - 26 * 3600000 }, { id: "3", name: "Release form", status: "Declined", at: now - 4 * 86400000 }];
  const chartData = Array.from({ length: 14 }, (_, i) => ({ date: new Date(now - (13 - i) * 86400000), value: 20 + Math.round(12 * Math.sin(i / 2) + i * 2) }));
  const events = [{ id: "e1", type: "email.delivered", status: "success", at: now - 60000 }, { id: "e2", type: "email.sent", status: "attempting", at: now - 120000 }, { id: "e3", type: "email.bounced", status: "failed", at: now - 7200000 }];
  const log = [{ id: "a", text: "POST /v1/documents 201" }, { id: "b", text: "GET /v1/documents 200" }];
  const tl = [{ title: "Created", at: now - 86400000, tone: "mute" }, { title: "Sent to Dana", at: now - 7200000, tone: "info" }, { title: "Waiting for Dana", detail: "Reminder in 2 days", tone: "warn", live: true }];
  const code = [{ id: "curl", label: "cURL", code: "curl https://api.docustay.app/v1/documents \\\n  -H 'Authorization: Bearer ds_live_…' \\\n  -d @document.json" }, { id: "js", label: "JavaScript", code: "const doc = await docustay.documents.create({ title: 'NDA' });" }];
  const menuItems = [{ label: "Open", icon: "external-link" }, { label: "Copy link", icon: "link" }, { separator: true }, { label: "Void", icon: "trash", danger: true }];
</script>
<svelte:head><title>Components</title><meta name="robots" content="noindex, nofollow" /></svelte:head>
<main class="mx-auto grid max-w-6xl gap-10 px-4 py-8" data-testid="gallery">
  <PageHeader title="Components" line="Every base, portal and website piece, on the account theme.">{#snippet actions()}<AppearanceMenu placement="bottom-end" />{/snippet}</PageHeader>

  <section class="grid gap-4"><h2 class="eyebrow">Controls</h2>
    <div class="flex flex-wrap items-center gap-6"><Toggle bind:checked={on} label="Test mode" hint="Documents go only to you" /><Segment bind:value={seg} options={[{ value: "board", label: "Board", icon: "board" }, { value: "list", label: "List", icon: "list" }]} /><FilterSelect bind:value={status} placeholder="All statuses" options={[{ value: "", label: "All statuses" }, { value: "waiting", label: "Waiting" }, { value: "signed", label: "Signed" }]} />
      <button class="btn primary" onclick={() => (dlg = true)}>Open dialog <Kbd mod>K</Kbd></button><Menu items={menuItems} /><Tip text="Copy the link"><button class="btn quiet !p-2" aria-label="Link"><Icon name="link" /></button></Tip><CopyButton value="ds_live_123" label="Copy" /></div>
    <Tabs bind:value={tab} items={[{ value: "a", label: "Overview" }, { value: "b", label: "People" }, { value: "c", label: "Activity" }]}>{#snippet panel(v)}<p class="text-mute">Panel {v}</p>{/snippet}</Tabs>
    <PinCode bind:value={pin} /><div class="grid max-w-md gap-4"><Meter value={72} label="Documents this month" detail="11 of 15" auto /><Meter value={100} label="Full" auto /><Range bind:value={rng} label="Slider" marks={[{ value: 0, label: "0" }, { value: 50, label: "50" }, { value: 100, label: "100" }]} /></div>
    <div class="flex flex-wrap gap-2"><StatusChip tone="ok">Signed</StatusChip><StatusChip tone="warn" live>Waiting</StatusChip><StatusChip tone="bad">Declined</StatusChip><StatusChip tone="info" spin>Attempting</StatusChip><StatusChip tone="mute" dot={false}>Draft</StatusChip><span class="text-sm text-mute"><RelativeTime value={now - 3 * 60000} /></span></div>
  </section>

  <section class="grid gap-4"><h2 class="eyebrow">Portal</h2>
    <DataTable caption="Documents" columns={[{ key: "name", label: "Name" }, { key: "status", label: "Status" }, { key: "at", label: "Updated", align: "right" }]} {rows} href={() => "#"}>{#snippet cell(r, c)}{#if c.key === "status"}<StatusChip tone={r.status === "Signed" ? "ok" : r.status === "Declined" ? "bad" : "warn"}>{r.status}</StatusChip>{:else if c.key === "at"}<RelativeTime value={r.at} />{:else}{r[c.key]}{/if}{/snippet}</DataTable>
    <EmptyState title="No documents yet" line="Upload a PDF or write one and it appears here.">{#snippet art()}<Paper skeleton width={96} />{/snippet}{#snippet action()}<button class="btn primary">Upload your first document</button>{/snippet}</EmptyState>
    <DetailHeader title="NDA, Dana Reyes" subtitle="Sent 3 minutes ago" icon="file-text">{#snippet chips()}<StatusChip tone="warn" live>Waiting</StatusChip>{/snippet}{#snippet actions()}<button class="btn">Remind</button>{/snippet}</DetailHeader>
    <MetaGrid items={[{ label: "Document id", value: "doc_01HX9K2", copy: true, mono: true }, { label: "Sent", value: "Oct 7, 2026" }, { label: "Expires", value: "Nov 6, 2026" }]} />
    <div class="grid gap-4 md:grid-cols-2"><CopyField label="DNS record" value="v=spf1 include:amazonses.com ~all" /><SecretField label="Signing secret" value="whsec_abcdefghijklmnop" /></div>
    <div class="grid gap-6 md:grid-cols-2"><Timeline dotted items={tl} /></div>
    
    <div class="grid gap-6 rounded-xl border border-line p-5 md:grid-cols-4"><StatTile label="Sent" value={128} /><StatTile label="Signed" value={96} delta="75% of sent" /><StatTile label="Declined" value={3} tone="bad" /><div class="flex items-center gap-3"><Ring value={11} max={15} /><span class="text-sm text-mute">11 of 15</span></div></div>
    <div class="grid gap-6 md:grid-cols-[2fr_1fr]"><AreaChart data={chartData} label="Documents per day" /><div class="grid content-start gap-4"><LegendRow rows={[{ name: "NDA", color: "var(--brand)", value: 61 }, { name: "Coaching agreement", color: "var(--ok)", value: 28 }, { name: "Release form", color: "var(--warn)", value: 11 }]} /><Spark values={[3, 5, 4, 8, 7, 11, 9]} /><Bars data={chartData.map((d) => ({ label: d.date.toDateString(), value: d.value }))} height={60} /></div></div>
    <div class="grid gap-3 md:grid-cols-3"><RateCard label="Delivered" rate={98} count="124" /><RateCard label="Bounced" rate={2} tone="bad" count="2" /><RateCard label="Opened" rate={64} tone="warn" count="80" /></div>
    <div class="grid gap-3 md:grid-cols-2"><IntegrationCard name="Stripe" line="Take payment while signing" icon="credit-card" status="Connected" tone="ok" /><IntegrationCard name="Webhooks" line="2 endpoints" icon="webhook" status="Healthy" tone="ok" /></div>
    <Flow steps={[{ title: "Add records", line: "Copy three DNS records", icon: "globe", state: "done" }, { title: "Verify", line: "We check every few minutes", icon: "shield-check", state: "current" }, { title: "Send", line: "From your own domain", icon: "mail" }]} />
    <div class="grid gap-4 md:grid-cols-2"><CodeWindow title="Create a document" tabs={code} highlight={[2]} /><EmailPreview from="Your Company <hello@yourco.com>" subject="Please sign: NDA" html="<body style='font-family:sans-serif;padding:20px;color:#15171c'><p>Hi Dana,</p><p>Please sign the NDA.</p></body>" height={200} /></div>
    <div class="flex flex-wrap items-center gap-6"><Frame title="docustay.app" class="w-72"><div class="p-6 text-center text-mute">Window</div></Frame><Paper skeleton width={120} /><span class="flex gap-3 text-mute"><Brand name="github" /><Brand name="stripe" /><Brand name="node" /><Brand name="python" /></span></div>
  </section>

  <section class="grid gap-4"><h2 class="eyebrow">Website</h2>
    <DotGrid glow class="rounded-2xl border border-line p-10"><div class="grid justify-items-start gap-4"><RainbowPill>Docustay 1.0 is here</RainbowPill><h2 class="t-h1"><GradientText accent="signed.">Send it. Get it</GradientText></h2><div class="flex gap-2"><MethodPill method="GET" /><MethodPill method="POST" /><MethodPill method="DELETE" /></div></div></DotGrid>
    <EventPicker events={[{ id: "a", label: "document.signed", line: "Everyone signed", payload: { type: "document.signed", id: "doc_1" } }, { id: "b", label: "document.declined", line: "Someone declined", payload: { type: "document.declined", id: "doc_2" } }]} />
    <div class="grid gap-4 md:grid-cols-3"><PlanCard name="Free" price="$0" line="15 documents a month" features={["API and webhooks", "Test mode"]} />{#snippet go()}<button class="btn primary w-full">Start</button>{/snippet}<PlanCard name="Pro" price="$39" per="/ month" featured chip="Founders $25" features={["Unlimited documents", "Your own email domain"]} cta={go} /><PlanCard name="Self-host" price="$390" per="/ year" features={["Your servers", "Commercial licence available"]} /></div>
    <VolumeSlider bind:value={vol} steps={[{ value: 0, label: "0" }, { value: 250, label: "250" }, { value: 500, label: "500" }, { value: 1000, label: "1,000" }]} label="Documents per month" estimate={(v) => `${v} documents a month is about $${v <= 15 ? 0 : 39}.`} />
    <CompareTable columns={["Free", "Pro"]} groups={[{ title: "Sending", rows: [{ label: "Documents per month", values: ["15", "Unlimited"] }, { label: "Own email domain", values: [false, true] }] }]} />
    <div class="grid gap-4 md:grid-cols-3"><div><ParamRow name="title" type="string" required>The document's name.</ParamRow><ParamRow name="expires_in_days" type="integer">Days until it expires.</ParamRow></div></div>
    <ChangelogEntry date="2026-10-07" title="A changelog entry" tag="New"><p>What changed, in plain words.</p></ChangelogEntry>
    <div class="flex items-center gap-3"><CopyPage markdown="# Page" url="https://docustay.app/docs/x" /></div>
  </section>
</main>
<Dialog bind:open={dlg} title="Send to a list" description="Everyone on the list gets their own copy.">Body text.{#snippet footer()}<button class="btn" onclick={() => (dlg = false)}>Cancel</button><button class="btn primary" onclick={() => (dlg = false)}>Send <Kbd mod>↵</Kbd></button>{/snippet}</Dialog>
